package com.reevil.client.canon;

import com.reevil.entity.BioMonster;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.core.registries.BuiltInRegistries;

/** Generated by tools/canon_moves.py: shows a creature's mutation parts only while its mutation stage matches. */
public final class CanonVisuals {
    private CanonVisuals() {}
    private static ModelPart part(ModelPart root, String path) {
        ModelPart p = root;
        for (String s : path.split("/")) { if (!p.hasChild(s)) return null; p = p.getChild(s); }
        return p;
    }
    public static void apply(ModelPart root, BioMonster e) {
        String id = BuiltInRegistries.ENTITY_TYPE.getKey(e.getType()).getPath();
        int mut = e.getMut();
        switch (id) {
            case "javo" -> {
                { ModelPart p = part(root, "base/torso/armR/foreR/mutBlade"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/mutWingL"); if (p != null) p.visible = mut == 2; }
                { ModelPart p = part(root, "base/torso/mutWingR"); if (p != null) p.visible = mut == 2; }
                { ModelPart p = part(root, "base/mutTail"); if (p != null) p.visible = mut == 3; }
                { ModelPart p = part(root, "base/torso/armL/foreL/mutClaw"); if (p != null) p.visible = mut == 4; }
            }
            case "wesker" -> {
                { ModelPart p = part(root, "base/torso/uroT1"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/uroT2"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/uroT3"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/uroT4"); if (p != null) p.visible = mut == 1; }
            }
            default -> {}
        }
    }
}
